<?php
declare(strict_types=1);
define('MEDICINE_GOVERNANCE_LIBRARY',true);
require __DIR__.'/medicine-governance.php';

class MedicineV1Policy extends App\Services\MedicineGovernancePolicy {
    // Legacy synthetic fixture only; never used by production or Phase 3.22 tests.
    public function requireQualificationBinding(App\Repositories\MedicineGovernanceRepository $repository,array $grant,string $scope):array {$this->requireQualification($grant,$scope);return [];}
    public function __construct(public array $configuration) {}
    protected function settings():array {return $this->configuration;}
}
class MedicineV1Inner extends MedicineMemoryRepository {
    public ?MedicineV1Memory $governance=null;
    public function transaction(callable $action):mixed {return $this->governance?$this->governance->transaction($action):parent::transaction($action);}
}
class MedicineV1Memory extends MedicineGovernanceMemory {
    public array $pilotRows=[];
    public function transaction(callable $action):mixed {$before=$this->pilotRows;try{return parent::transaction($action);}catch(Throwable $e){$this->pilotRows=$before;throw $e;}}
    public function pilotRecords(string $code,string $scope):array {return array_values(array_filter($this->pilotRows,fn($r)=>$r['pilot_code']===$code&&$r['scope']===$scope));}
    public function pilotTarget(string $scope,string $id):?array {return $this->pilotRows[$scope.':'.$id]??null;}
    public function insertPilot(string $code,string $scope,string $id,string $event):void {$this->pilotRows[$scope.':'.$id]=['pilot_code'=>$code,'scope'=>$scope,'creation_event_id'=>$event];}
}
function medicineV1Credential(string $profession='doctor'):string {return json_encode(['profession'=>$profession,'registration'=>'SYNTHETIC_ONLY','jurisdiction'=>'SYNTHETIC','authority'=>'SYNTHETIC','status'=>'verified','verified_at'=>'2026-01-01 00:00:00.000001','renewal_due'=>'2031-01-01 00:00:00.000001','verifier'=>8],JSON_THROW_ON_ERROR);}
function medicineV1Settings():array {return ['owner_user_ids'=>[8],'registry_operator_user_ids'=>[],'deployment_operator_user_ids'=>[],'pilot_enabled'=>true,'pilot_code'=>'synthetic_v1','pilot_limit'=>10,'pilot_substances'=>[['substance_id'=>'2','unambiguous'=>true,'representative_reference'=>'SYNTHETIC_ENTITY_2'],['substance_id'=>'10','unambiguous'=>true,'representative_reference'=>'SYNTHETIC_ENTITY_10']],'pilot_actions'=>['register_reference','create_identity','create_presentation'],'authoritative_tiers'=>[1,2],'evidence_sources'=>['SYNTHETIC_TEST_ONLY'=>['active'=>true,'tier'=>1,'scopes'=>['chemical','composition','presentation'],'valid_until'=>'2030-01-01 00:00:00.000001','records'=>[]]]];}
function medicineV1Fixture():array {
    [$original]=medicineFixture();$inner=new MedicineV1Inner();$inner->data=$original->data;foreach(['refs','identities','ingredients','presentations','strengths'] as $table){$inner->data[$table]=[];}
    $r=new MedicineV1Memory($inner);$inner->governance=$r;$p=new MedicineV1Policy(medicineV1Settings());[$s,$a,$authority,$e]=medicineGovernanceObjects($r,$p);
    $a->actorId=8;
    foreach([[1,'contributor'],[4,'editor'],[2,'reviewer'],[4,'steward']] as [$actor,$cap]){$input=['user_id'=>$actor,'capability'=>$cap,'scope'=>'catalog','expires_at'=>'2030-01-01 00:00:00.000001','rationale'=>'Synthetic issuance'];if($cap==='reviewer'){$input+=['qualification_reference'=>medicineV1Credential(),'qualification_scope'=>'catalog'];}$s->grantAuthority($input);}
    $a->actorId=1;$identity=new App\Services\MedicineIdentityService($inner,new App\Services\MedicineCanonicalizer(),$a,new MedicineTestProfiles($inner),$authority);
    return [$r,$s,$a,$authority,$e,$identity,$p];
}
function medicineV1Appraise(MedicineV1Policy $p,App\Services\MedicineEligibilityService $e,string $scope,string $id):array {
    $evidence=medicineSyntheticEvidence();$p->configuration['evidence_sources'][$evidence['issuer']]['records'][]=$evidence+['scope'=>$scope,'target_id'=>$id,'snapshot_hash'=>hash('sha256',$e->json($e->snapshot($scope,$id))),'identity_appraised'=>true,'valid_until'=>'2030-01-01 00:00:00.000001'];return $evidence;
}
function medicineV1Verify(array $f,string $id):void {
    [$r,$s,$a,$authority,$e,$identity,$p]=$f;$a->actorId=1;
    $s->assessChemical($id,medicineGovernanceInput($r,$e,'chemical',$id,['state'=>'candidate','rationale'=>'Fresh explicit assessment']));
    $evidence=medicineV1Appraise($p,$e,'chemical',$id);
    $s->submit('chemical',$id,medicineGovernanceInput($r,$e,'chemical',$id,['rationale'=>'Draft identity evidence','evidence'=>$evidence]));
    $a->actorId=2;$s->verify('chemical',$id,medicineGovernanceInput($r,$e,'chemical',$id,['rationale'=>'Independent identity decision','evidence'=>$evidence]));$e->requireCurrent('chemical',$id);
}
if(defined('MEDICINE_POLICY_LIBRARY')){return;}

medicineTest('owner admin accepted ordinary actor denied and no self escalation',function(){[$r,$s,$a,$auth]=medicineV1Fixture();$auth->requireOperator(8,'administrator');medicineReject(fn()=>$auth->requireOperator(1,'administrator'),403);$a->actorId=8;medicineReject(fn()=>$s->grantAuthority(['user_id'=>8,'capability'=>'administrator','scope'=>'catalog','expires_at'=>'2030-01-01 00:00:00.000001','rationale'=>'Self']),403);});
medicineTest('delegated administrator grant revoke remains owner controlled',function(){[$r,$s,$a,$auth]=medicineV1Fixture();$a->actorId=8;$g=$s->grantAuthority(['user_id'=>6,'capability'=>'administrator','scope'=>'catalog','expires_at'=>'2030-01-01 00:00:00.000001','rationale'=>'Delegated']);$auth->requireOperator(6,'administrator');$a->actorId=6;medicineReject(fn()=>$s->grantAuthority(['user_id'=>1,'capability'=>'registry','scope'=>'catalog','expires_at'=>'2030-01-01 00:00:00.000001','rationale'=>'Escalation']),403);$a->actorId=8;$s->revokeAuthority($g['grant_id'],'Owner revocation');medicineReject(fn()=>$auth->requireOperator(6,'administrator'),403);medicineCheck(count($r->events('grant',$g['grant_id']))===2);});
foreach(['doctor','pharmacist'] as $profession){medicineTest('qualified '.$profession.' accepted without public credential output',function()use($profession){$f=medicineV1Fixture();[$r,$s,$a,$auth,$e,$i,$p]=$f;$r->grantRows['3']['qualification_reference']=medicineV1Credential($profession);$ref=$i->registerChemicalReference(['substance_id'=>'2']);medicineV1Verify($f,$ref['chemical_ref_id']);$a->actorId=1;$output=$s->inspect('chemical',$ref['chemical_ref_id']);medicineCheck(!str_contains(json_encode($output),'SYNTHETIC_ONLY'));});}
foreach(['profession','missing','unverified','expired','verifier','future','jurisdiction'] as $bad){medicineTest('credential rejects '.$bad,function()use($bad){[$r,$s,$a,$auth]=medicineV1Fixture();$c=json_decode(medicineV1Credential(),true);switch($bad){case 'profession':$c['profession']='other';break;case 'missing':$r->grantRows['3']['qualification_reference']=null;break;case 'unverified':$c['status']='unverified';break;case 'expired':$c['renewal_due']='2021-01-01 00:00:00.000001';break;case 'verifier':$c['verifier']=1;break;case 'future':$c['verified_at']='2032-01-01 00:00:00.000001';break;case 'jurisdiction':$c['jurisdiction']='';}if($bad!=='missing'){$r->grantRows['3']['qualification_reference']=json_encode($c);}medicineReject(fn()=>$auth->requireGovernance(2,'reviewer','chemical'),403);});}
foreach([[1,true],[2,true],[3,false],[4,false],[5,false]] as [$tier,$accept]){medicineTest('initial evidence tier '.$tier,function()use($tier,$accept){[$r,$s,$a,$auth,$e,$i,$p]=medicineV1Fixture();$id=$i->registerChemicalReference(['substance_id'=>'2'])['chemical_ref_id'];$evidence=medicineV1Appraise($p,$e,'chemical',$id);$p->configuration['evidence_sources'][$evidence['issuer']]['tier']=$tier;$action=fn()=>$p->requireEvidenceFor($evidence,'chemical',$id,hash('sha256',$e->json($e->snapshot('chemical',$id))));if($accept){$action();medicineCheck(true);}else{medicineReject($action,403);}});}
foreach([3,4] as $tier){medicineTest('configured authoritative tier '.$tier,function()use($tier){[$r,$s,$a,$auth,$e,$i,$p]=medicineV1Fixture();$p->configuration['authoritative_tiers']=[1,2,$tier];$p->configuration['evidence_sources']['SYNTHETIC_TEST_ONLY']['tier']=$tier;$id=$i->registerChemicalReference(['substance_id'=>'2'])['chemical_ref_id'];$ev=medicineV1Appraise($p,$e,'chemical',$id);$p->requireEvidenceFor($ev,'chemical',$id,hash('sha256',$e->json($e->snapshot('chemical',$id))));medicineCheck(true);});}
medicineTest('tier five cannot be promoted through configuration',function(){[$r,$s,$a,$auth,$e,$i,$p]=medicineV1Fixture();$p->configuration['authoritative_tiers']=[1,2,5];$p->configuration['evidence_sources']['SYNTHETIC_TEST_ONLY']['tier']=5;medicineReject(fn()=>$p->requireEvidence(medicineSyntheticEvidence(),'chemical'),403);});
foreach(['therapeutic','unrelated','retracted','changed_digest'] as $bad){medicineTest('evidence denies '.$bad,function()use($bad){[$r,$s,$a,$auth,$e,$i,$p]=medicineV1Fixture();$id=$i->registerChemicalReference(['substance_id'=>'2'])['chemical_ref_id'];$ev=medicineV1Appraise($p,$e,'chemical',$id);$hash=hash('sha256',$e->json($e->snapshot('chemical',$id)));if($bad==='therapeutic'){$ev['kind']='therapeutic';}if($bad==='unrelated'){$id='999';}if($bad==='retracted'){$p->configuration['evidence_sources'][$ev['issuer']]['active']=false;}if($bad==='changed_digest'){$ev['source_sha256']=str_repeat('b',64);}medicineReject(fn()=>$p->requireEvidenceFor($ev,'chemical',$id,$hash),403);});}
medicineTest('candidate creation submission review and composition editing are audited',function(){ $f=medicineV1Fixture();[$r,$s,$a,$auth,$e,$i,$p]=$f;$id=$i->registerChemicalReference(['substance_id'=>'2'])['chemical_ref_id'];medicineCheck($r->pilotTarget('chemical',$id)['pilot_code']==='synthetic_v1'&&$r->latest('chemical',$id)['action']==='create');medicineV1Verify($f,$id);$a->actorId=1;$m=$i->createMedicine(['ingredients'=>[['substance_id'=>'2']]]);$a->actorId=4;$s->editMetadata('composition',$m['medicine_identity_id'],medicineGovernanceInput($r,$e,'composition',$m['medicine_identity_id'],['display_name'=>'Synthetic draft','rationale'=>'Draft edit']));$ev=medicineV1Appraise($p,$e,'composition',$m['medicine_identity_id']);$s->submit('composition',$m['medicine_identity_id'],medicineGovernanceInput($r,$e,'composition',$m['medicine_identity_id'],['rationale'=>'Submit','evidence'=>$ev]));$a->actorId=2;$result=$s->verify('composition',$m['medicine_identity_id'],medicineGovernanceInput($r,$e,'composition',$m['medicine_identity_id'],['rationale'=>'Independent','evidence'=>$ev]));medicineCheck($result['published']===false);$e->requireCurrent('composition',$m['medicine_identity_id']);});
medicineTest('creator with reviewer credential still cannot self approve',function(){[$r,$s,$a,$auth,$e,$i,$p]=medicineV1Fixture();$id=$i->registerChemicalReference(['substance_id'=>'2'])['chemical_ref_id'];$s->assessChemical($id,medicineGovernanceInput($r,$e,'chemical',$id,['state'=>'candidate','rationale'=>'Assess']));$ev=medicineV1Appraise($p,$e,'chemical',$id);$s->submit('chemical',$id,medicineGovernanceInput($r,$e,'chemical',$id,['rationale'=>'Submit','evidence'=>$ev]));$a->actorId=8;$s->grantAuthority(['user_id'=>1,'capability'=>'reviewer','scope'=>'catalog','expires_at'=>'2030-01-01 00:00:00.000001','qualification_reference'=>medicineV1Credential(),'qualification_scope'=>'catalog','rationale'=>'Synthetic reviewer']);$a->actorId=1;medicineReject(fn()=>$s->verify('chemical',$id,medicineGovernanceInput($r,$e,'chemical',$id,['rationale'=>'Self','evidence'=>$ev])),403);});
medicineTest('review requires submitted current revision and reject remains historical',function(){[$r,$s,$a,$auth,$e,$i,$p]=medicineV1Fixture();$id=$i->registerChemicalReference(['substance_id'=>'2'])['chemical_ref_id'];$s->assessChemical($id,medicineGovernanceInput($r,$e,'chemical',$id,['state'=>'candidate','rationale'=>'Assess']));$ev=medicineV1Appraise($p,$e,'chemical',$id);$a->actorId=2;medicineReject(fn()=>$s->verify('chemical',$id,medicineGovernanceInput($r,$e,'chemical',$id,['rationale'=>'No submit','evidence'=>$ev])),403);$a->actorId=1;$s->submit('chemical',$id,medicineGovernanceInput($r,$e,'chemical',$id,['rationale'=>'Submit','evidence'=>$ev]));$a->actorId=2;$stale=medicineGovernanceInput($r,$e,'chemical',$id,['rationale'=>'Rejected']);$s->reject('chemical',$id,$stale);medicineReject(fn()=>$s->verify('chemical',$id,$stale+['evidence'=>$ev]),409);medicineCheck($r->assessment($id)['assessment_state']==='unresolved');});
medicineTest('invalidation requires explicit reassessment new submission and independent review',function(){ $f=medicineV1Fixture();[$r,$s,$a,$auth,$e,$i]=$f;$id=$i->registerChemicalReference(['substance_id'=>'2'])['chemical_ref_id'];medicineV1Verify($f,$id);$old=$r->latest('chemical',$id);$a->actorId=4;$s->invalidate('chemical',$id,['expected_revision'=>$r->target('chemical',$id)['metadata_revision'],'state'=>'invalidated','rationale'=>'Invalidated']);$a->actorId=2;medicineReject(fn()=>$s->verify('chemical',$id,medicineGovernanceInput($r,$e,'chemical',$id,['rationale'=>'Automatic','evidence'=>medicineSyntheticEvidence()])),403);medicineReject(fn()=>$e->requireCurrent('chemical',$id),409);medicineV1Verify($f,$id);medicineCheck($r->eventRows[$old['id']]===$old&&$r->latest('chemical',$id)['revision']>$old['revision']);});
